CREATE OR REPLACE FUNCTION public.audit_operational_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,entity_type,entity_id,action,changes) VALUES(auth.uid(),TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP,jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END)); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_stores AFTER INSERT OR UPDATE OR DELETE ON public.stores FOR EACH ROW EXECUTE FUNCTION public.audit_operational_change();
CREATE TRIGGER audit_plannings AFTER INSERT OR UPDATE OR DELETE ON public.plannings FOR EACH ROW EXECUTE FUNCTION public.audit_operational_change();
CREATE TRIGGER audit_routes AFTER INSERT OR UPDATE OR DELETE ON public.routes FOR EACH ROW EXECUTE FUNCTION public.audit_operational_change();
CREATE TRIGGER audit_planning_stores AFTER INSERT OR UPDATE OR DELETE ON public.planning_stores FOR EACH ROW EXECUTE FUNCTION public.audit_operational_change();
CREATE TRIGGER audit_settings AFTER INSERT OR UPDATE ON public.operational_settings FOR EACH ROW EXECUTE FUNCTION public.audit_operational_change();
CREATE OR REPLACE FUNCTION public.validate_planning_store_duplicate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.planning_id::text || NEW.store_id::text)); IF EXISTS(SELECT 1 FROM public.planning_stores WHERE planning_id=NEW.planning_id AND store_id=NEW.store_id AND id<>NEW.id) AND NULLIF(btrim(NEW.duplicate_justification),'') IS NULL THEN RAISE EXCEPTION 'Uma loja duplicada exige justificativa operacional.'; END IF; IF NEW.route_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.routes WHERE id=NEW.route_id AND planning_id=NEW.planning_id AND NOT archived) THEN RAISE EXCEPTION 'Selecione uma rota ativa deste planejamento.'; END IF; NEW.updated_by=auth.uid(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.classify_planning_volume() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s public.operational_settings; BEGIN IF TG_OP='INSERT' OR NEW.predicted_volume IS DISTINCT FROM OLD.predicted_volume THEN SELECT * INTO s FROM public.operational_settings LIMIT 1; IF s.low_volume_max IS NOT NULL AND s.medium_volume_max IS NOT NULL THEN NEW.volume_class=CASE WHEN NEW.predicted_volume<=s.low_volume_max THEN 'baixo'::public.volume_class WHEN NEW.predicted_volume<=s.medium_volume_max THEN 'medio'::public.volume_class ELSE 'alto'::public.volume_class END; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER classify_volume BEFORE INSERT OR UPDATE ON public.planning_stores FOR EACH ROW EXECUTE FUNCTION public.classify_planning_volume();
ALTER TABLE public.operational_settings ADD CONSTRAINT ordered_volume_limits CHECK ((low_volume_max IS NULL AND medium_volume_max IS NULL) OR (low_volume_max IS NOT NULL AND medium_volume_max IS NOT NULL AND medium_volume_max>low_volume_max)) NOT VALID;
ALTER TABLE public.operational_settings VALIDATE CONSTRAINT ordered_volume_limits;
CREATE OR REPLACE FUNCTION public.archive_route(_id uuid, _archived boolean) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF _archived THEN UPDATE public.planning_stores SET route_id=NULL WHERE route_id=_id; END IF; UPDATE public.routes SET archived=_archived WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.archive_route(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.archive_route(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.copy_planning(_source uuid,_date date,_shift public.work_shift) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE target uuid; r record; newroute uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.plannings WHERE id=_source) THEN RAISE EXCEPTION 'Planejamento não encontrado'; END IF; INSERT INTO public.plannings(collection_date,shift) VALUES(_date,_shift) RETURNING id INTO target; FOR r IN SELECT * FROM public.routes WHERE planning_id=_source AND NOT archived LOOP INSERT INTO public.routes(planning_id,code,responsible,vehicle,capacity_packages,needs_support,needs_extra_route,notes) VALUES(target,r.code,r.responsible,r.vehicle,r.capacity_packages,r.needs_support,r.needs_extra_route,r.notes) RETURNING id INTO newroute; END LOOP; INSERT INTO public.planning_stores(planning_id,store_id,route_id,store_code_snapshot,store_name_snapshot,full_address_snapshot,region_snapshot,predicted_volume,volume_class,needs_extra_route,needs_support,support_type,priority,notes,duplicate_justification) SELECT target,ps.store_id,nr.id,ps.store_code_snapshot,ps.store_name_snapshot,ps.full_address_snapshot,ps.region_snapshot,ps.predicted_volume,ps.volume_class,ps.needs_extra_route,ps.needs_support,ps.support_type,ps.priority,ps.notes,ps.duplicate_justification FROM public.planning_stores ps LEFT JOIN public.routes oldr ON oldr.id=ps.route_id LEFT JOIN public.routes nr ON nr.planning_id=target AND nr.code=oldr.code WHERE ps.planning_id=_source ORDER BY ps.created_at,ps.id; RETURN target; END $$;
REVOKE ALL ON FUNCTION public.copy_planning(uuid,date,public.work_shift) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.copy_planning(uuid,date,public.work_shift) TO authenticated;
CREATE OR REPLACE FUNCTION public.confirm_planning(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.planning_stores WHERE planning_id=_id) THEN RAISE EXCEPTION 'Adicione lojas antes de confirmar'; END IF; IF EXISTS(SELECT 1 FROM public.planning_stores WHERE planning_id=_id AND route_id IS NULL) THEN RAISE EXCEPTION 'Atribua uma rota a todas as lojas antes de confirmar'; END IF; UPDATE public.planning_stores SET status='confirmada' WHERE planning_id=_id; UPDATE public.routes SET status='confirmada' WHERE planning_id=_id AND NOT archived; UPDATE public.plannings SET status='confirmada' WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.confirm_planning(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.confirm_planning(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.import_first_mile(_date date,_shift public.work_shift,_rows jsonb,_update_existing boolean,_create_new boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE target uuid; item jsonb; sid uuid; rid uuid; psid uuid; added integer=0; updated integer=0; ignored integer=0; seen text[]='{}'; code text; existing public.stores; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows)>5000 THEN RAISE EXCEPTION 'Importe até 5.000 linhas por arquivo'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(_rows) LOOP code=btrim(item->>'store_code'); IF COALESCE(code,'')='' OR COALESCE(btrim(item->>'name'),'')='' THEN RAISE EXCEPTION 'ID e nome são obrigatórios'; END IF; IF code=ANY(seen) THEN RAISE EXCEPTION 'ID repetido no arquivo: %',code; END IF; seen=array_append(seen,code); SELECT * INTO existing FROM public.stores WHERE store_code=code; sid=existing.id; IF sid IS NULL AND NOT _create_new THEN ignored=ignored+1; CONTINUE; END IF; IF sid IS NULL THEN INSERT INTO public.stores(store_code,name,full_address,region,street,street_number,city) VALUES(code,item->>'name',COALESCE(item->>'full_address',''),COALESCE(item->>'region',''),COALESCE(item->>'street',''),COALESCE(item->>'street_number',''),COALESCE(item->>'city','')) RETURNING id INTO sid; ELSIF _update_existing THEN UPDATE public.stores SET name=COALESCE(NULLIF(item->>'name',''),name),full_address=COALESCE(NULLIF(item->>'full_address',''),full_address),region=COALESCE(NULLIF(item->>'region',''),region),street=COALESCE(NULLIF(item->>'street',''),street),street_number=COALESCE(NULLIF(item->>'street_number',''),street_number),city=COALESCE(NULLIF(item->>'city',''),city),active=true WHERE id=sid; END IF; IF target IS NULL THEN INSERT INTO public.plannings(collection_date,shift) VALUES(_date,_shift) ON CONFLICT(collection_date,shift) DO UPDATE SET updated_at=now() RETURNING id INTO target; END IF; rid=NULL; IF NULLIF(btrim(item->>'route'),'') IS NOT NULL THEN INSERT INTO public.routes(planning_id,code) VALUES(target,btrim(item->>'route')) ON CONFLICT(planning_id,code) DO UPDATE SET archived=false RETURNING id INTO rid; END IF; SELECT id INTO psid FROM public.planning_stores WHERE planning_id=target AND store_id=sid ORDER BY created_at LIMIT 1; IF psid IS NOT NULL AND NOT _update_existing THEN ignored=ignored+1; CONTINUE; END IF; IF psid IS NULL THEN INSERT INTO public.planning_stores(planning_id,store_id,route_id,store_code_snapshot,store_name_snapshot,full_address_snapshot,region_snapshot,predicted_volume,notes) VALUES(target,sid,rid,code,item->>'name',COALESCE(NULLIF(item->>'full_address',''),existing.full_address,''),COALESCE(NULLIF(item->>'region',''),existing.region,''),COALESCE((item->>'predicted_volume')::integer,0),COALESCE(item->>'notes','')); added=added+1; ELSE UPDATE public.planning_stores SET route_id=COALESCE(rid,route_id),store_name_snapshot=COALESCE(NULLIF(item->>'name',''),store_name_snapshot),full_address_snapshot=COALESCE(NULLIF(item->>'full_address',''),full_address_snapshot),region_snapshot=COALESCE(NULLIF(item->>'region',''),region_snapshot),predicted_volume=COALESCE((item->>'predicted_volume')::integer,predicted_volume),notes=COALESCE(NULLIF(item->>'notes',''),notes) WHERE id=psid; updated=updated+1; END IF; END LOOP; RETURN jsonb_build_object('added',added,'updated',updated,'ignored',ignored); END $$;
REVOKE ALL ON FUNCTION public.import_first_mile(date,public.work_shift,jsonb,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_first_mile(date,public.work_shift,jsonb,boolean,boolean) TO authenticated;